package com.aditya.fefo.service; import com.aditya.fefo.dto.DashboardDtos.Summary; import com.aditya.fefo.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDate;
@Service public class DashboardService {private final ProductRepository p;private final BatchRepository b;public DashboardService(ProductRepository p,BatchRepository b){this.p=p;this.b=b;} public Summary summary(){LocalDate n=LocalDate.now();return new Summary(p.countByActiveTrue(),b.count(),b.sumAvailable(),b.sumReserved(),b.countByExpiryDateBetweenAndExpiredFalse(n,n.plusDays(7)),b.countByExpiryDateBetweenAndExpiredFalse(n,n.plusDays(30)),b.countByExpiredTrue());}}
